<?php $pageTitle = 'Themes'; ?>
<div class="card"><h2>Install theme</h2><p class="muted">Upload a trusted AfiuCMS theme ZIP. The package must contain <span class="code">theme.json</span> at its root.</p><p class="danger-note"><strong>Important:</strong> theme PHP files execute server-side code. Treat third-party themes like plugins/applications and install only trusted packages.</p><form class="row" method="post" action="/admin/themes/upload" enctype="multipart/form-data"><?= csrf_field() ?><input style="max-width:430px" type="file" name="theme" accept=".zip,application/zip" required><button class="btn" type="submit">Install ZIP</button></form></div><br><div class="theme-grid"><?php foreach ($themes as $theme): ?><div class="theme-card"><div class="theme-preview"><?= e($theme['name']) ?></div><div class="theme-info"><div class="row between"><div><strong><?= e($theme['name']) ?></strong><div class="muted">v<?= e($theme['version']) ?> · <?= e($theme['author'] ?? 'Unknown') ?></div></div><?php if (!empty($theme['active'])): ?><span class="btn small primary">Active</span><?php endif; ?></div><p class="muted"><?= e($theme['description'] ?? '') ?></p><?php if (empty($theme['active'])): ?><form method="post" action="/admin/themes/<?= e($theme['slug']) ?>/activate"><?= csrf_field() ?><button class="btn small" type="submit">Activate</button></form><?php endif; ?></div></div><?php endforeach; ?></div>
